files.content:
:root {
  --bg: #1b1b2f;
  --card: #2e2e4a;
  --accent: #ffcc66;
  --text: #f4f4f8;
  --muted: #b8b8d0;
  --border: #5a5a7a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 16px;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: min(100%, 420px);
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 #0e0e1a;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.subtitle {
  margin: 0 0 8px;
  color: var(--muted);
  font-size: 0.9rem;
}

label {
  margin-top: 8px;
  font-weight: 700;
  font-size: 0.95rem;
}

input, select, button {
  font: inherit;
  color: var(--text);
  background: #1f1f33;
  border: 3px solid var(--border);
  padding: 10px 12px;
  width: 100%;
  border-radius: 0;
}

input:focus-visible, select:focus-visible, button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button {
  margin-top: 16px;
  background: var(--accent);
  color: #1b1b2f;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
  box-shadow: 4px 4px 0 #0e0e1a;
}

button:hover { filter: brightness(1.08); }
button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #0e0e1a;
}

.result-box {
  margin-top: 16px;
  padding: 12px;
  background: #1f1f33;
  border: 3px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}

.result-label {
  color: var(--muted);
  font-size: 0.9rem;
  text-transform: uppercase;
}

#result {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.formulas {
  margin-top: 16px;
  border-top: 2px dashed var(--border);
  padding-top: 12px;
}

.formulas h2 {
  margin: 0 0 4px;
  font-size: 0.9rem;
  text-transform: uppercase;
  color: var(--muted);
}

.formulas p { margin: 4px 0; }

code {
  font-family: ui-monospace, 'Courier New', monospace;
  background: #1f1f33;
  padding: 2px 6px;
  border: 2px solid var(--border);
  display: inline-block;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.25rem; }
  #result { font-size: 1.2rem; }
}

const input = document.getElementById('temperature');
const direction = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const result = document.getElementById('result');

function convert() {
  const raw = input.value.trim();
  if (raw === '') {
    result.textContent = 'Error';
    return;
  }
  const value = Number(raw);
  if (!Number.isFinite(value)) {
    result.textContent = 'Error';
    return;
  }
  let converted;
  if (direction.value === 'c-to-f') {
    converted = value * 9 / 5 + 32;
  } else {
    converted = (value - 32) * 5 / 9;
  }
  result.textContent = converted.toFixed(2);
}

convertBtn.addEventListener('click', convert);

input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    convert();
  }
});

direction.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    convert();
  }
});
